/* Isolated preview enhancement. All original content and controls remain usable. */
(()=>{
 'use strict';
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 let manualPause=false;const running=new Set(),seen=new WeakSet(),counted=new Set();
 const ease='cubic-bezier(.22,1,.36,1)';
 const quiet=()=>reduced.matches||manualPause;
 const $=s=>document.querySelector(s);
 document.body.classList.add('motion-preview');
 function animate(el,frames,options={}){if(!el||quiet())return;const a=el.animate(frames,{duration:700,easing:ease,...options});running.add(a);a.finished.catch(()=>{}).finally(()=>running.delete(a));return a;}
 function enter(el,delay=0,kind='text'){if(!el)return;seen.add(el);animate(el,[{opacity:0,transform:`translateY(${kind==='image'?20:14}px)`,filter:kind==='text'?'blur(3px)':'blur(0px)'},{opacity:1,transform:'translateY(0)',filter:'blur(0px)'}],{duration:kind==='image'?850:650,delay,fill:'backwards'});}
 function geometry(host){let layer=host.querySelector(':scope>.motion-geometry');if(!layer){layer=document.createElement('div');layer.className='motion-geometry';layer.setAttribute('aria-hidden','true');layer.innerHTML=Array.from({length:18},(_,i)=>`<span class="geo-mark" style="--geo-delay:${(i%6)*22}ms"><span class="geo-box"><i></i><i></i><i></i><i></i></span><span class="geo-point">+</span></span>`).join('');host.prepend(layer);}layer.classList.remove('geometry-active');if(!quiet()){void layer.offsetWidth;layer.classList.add('geometry-active');}return layer;}
 const fields=[];
 function symbolField(host){const canvas=document.createElement('canvas');canvas.className='symbol-field';canvas.setAttribute('aria-hidden','true');host.append(canvas);const field={canvas,frame:0,started:0};fields.push(field);return field;}
 function draw(field,progress){const c=field.canvas,w=c.clientWidth,h=c.clientHeight;if(!w||!h)return;const dpr=Math.min(devicePixelRatio,1.5);if(c.width!==Math.round(w*dpr)||c.height!==Math.round(h*dpr)){c.width=Math.round(w*dpr);c.height=Math.round(h*dpr);}const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);ctx.font='9px monospace';ctx.textAlign='center';const step=w<350?12:13;const settle=1-Math.pow(1-progress,3);let n=0;
  for(let x=0;x<w;x+=step){const u=x/w;const ridge=.52-.22*Math.sin(u*5.3)-.1*Math.sin(u*13);for(let y=h*ridge;y<h*.97;y+=step){const depth=(y/h-ridge)/(1-ridge);const seed=(Math.sin(x*17+y*31)*43758.54)%1;const alpha=Math.max(0,(1-depth)*.5*(.45+Math.abs(seed)*.55))*Math.min(1,progress*3);if(alpha<.025)continue;ctx.fillStyle=`rgba(135,177,237,${alpha})`;const drift=(1-settle)*(Math.sin(n*1.7)*28+10);ctx.fillText(['·','+','-',':'][Math.abs(Math.floor(seed*97))%4],x+drift,y+(1-settle)*35);n++;}}
 }
 function runField(field){cancelAnimationFrame(field.frame);if(quiet()){draw(field,1);return;}field.started=performance.now();const tick=now=>{if(document.hidden||quiet()){draw(field,1);return;}const p=Math.min(1,(now-field.started)/1800);draw(field,p);if(p<1)field.frame=requestAnimationFrame(tick);};field.frame=requestAnimationFrame(tick);}
 const hero=$('#hero-stage'),heroField=symbolField(hero),footerField=symbolField($('.contact'));
 function opening(){geometry(hero);runField(heroField);enter($('.hero-title h1'),220);enter($('.hero-title p'),380);document.querySelectorAll('.corner-label').forEach((e,i)=>enter(e,490+i*35));enter($('.hero-register'),600,'image');}
 function countMetrics(container){container.querySelectorAll('.noodle-metrics strong').forEach((el,i)=>{const key=i+':'+el.textContent;if(counted.has(key)||quiet())return;counted.add(key);const text=el.firstChild;if(!text||text.nodeType!==3)return;const original=text.textContent,target=Number(original.replace(/,/g,''));if(!Number.isFinite(target)||target===0)return;const digits=original.includes('.')?1:0,commas=original.includes(',');el.setAttribute('aria-label',el.textContent);const start=performance.now();const finish=()=>{text.textContent=original;};const tick=now=>{if(!el.isConnected){return;}if(quiet()||document.hidden){finish();return;}const p=Math.min(1,(now-start)/1100),value=target*(1-Math.pow(1-p,3));text.textContent=commas?Math.round(value).toLocaleString('en-US'):value.toFixed(digits);if(p<1)requestAnimationFrame(tick);else finish();};requestAnimationFrame(tick);});}
 const viewport=new IntersectionObserver(entries=>{entries.forEach(({target,isIntersecting})=>{if(!isIntersecting)return;viewport.unobserve(target);if(target.matches('.noodle-metrics')){countMetrics(target);Array.from(target.children).forEach((e,i)=>enter(e,i*55));}else if(target===footerField.canvas){runField(footerField);}else if(!seen.has(target)){enter(target,Number(target.dataset.motionDelay)||0,target.matches('figure,.project,.media-card,.hero-film,.noodle-study')?'image':'text');}});},{threshold:.09});
 function watch(scope,selectors){scope.querySelectorAll(selectors).forEach((el,i)=>{if(seen.has(el))return;el.dataset.motionDelay=String((i%3)*45);viewport.observe(el);});}
 function panelMotion(){viewport.disconnect();watch(document,'.profile-index,.profile-copy,.profile-bio,.hero-film,.position>.section-label,.practice-grid>div,.section-heading,.project,.about-name,.about-content,.contact>.mono,.contact>a');watch($('#detail-panel'),'.case-thesis,.noodle-accounts,.case-contactsheet figure,.process-heading,.case-step,.case-note,.media-heading,.media-card,.noodle-platform-heading,.noodle-study,.noodle-audience,.noodle-cooperation,.noodle-collaboration-evidence,.noodle-next');const metrics=$('.noodle-metrics');if(metrics)viewport.observe(metrics);viewport.observe(footerField.canvas);}
 const originalRender=window.render;window.render=function(...args){const result=originalRender.apply(this,args);watch($('#projects'),'.project');return result;};
 const originalTab=window.tab;window.tab=function(...args){const result=originalTab.apply(this,args);panelMotion();animate($('#detail-panel'),[{opacity:.25},{opacity:1}],{duration:280});return result;};
 const originalOpen=window.openProject;window.openProject=function(...args){const wasOpen=$('#detail').open;const result=originalOpen.apply(this,args);geometry($('.case-hero'));if(!wasOpen)animate($('#detail'),[{opacity:0,transform:'translateY(20px) scale(.985)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:480});enter($('.case-kicker'),100);enter($('#detail-title'),190);enter($('#detail-intro'),280);enter($('#case-keywords'),340);enter($('#case-cover'),260,'image');return result;};
 $('#lightbox').addEventListener('close',()=>running.forEach(a=>{if(a.effect?.target===$('#large-image'))a.cancel();}));
 new MutationObserver(()=>{if($('#lightbox').open)animate($('#large-image'),[{opacity:0,transform:'scale(.97)'},{opacity:1,transform:'scale(1)'}],{duration:350});}).observe($('#lightbox'),{attributes:true,attributeFilter:['open']});
 const controls=document.createElement('aside');controls.className='preview-controls';controls.setAttribute('aria-label','动效版本预览控制');controls.innerHTML='<span>MOTION / 01</span><button type="button" data-replay>重播开场 ↺</button><button type="button" data-metrics>看数据动效 ↗</button><button type="button" data-quiet aria-pressed="false">减少动态</button>';document.body.append(controls);
 controls.querySelector('[data-replay]').addEventListener('click',()=>{window.scrollTo({top:0,behavior:'instant'});running.forEach(a=>a.cancel());opening();});
 controls.querySelector('[data-metrics]').addEventListener('click',()=>{counted.clear();window.openProject('noodle');requestAnimationFrame(()=>$('.noodle-metrics').scrollIntoView({block:'center',behavior:'instant'}));});
 function syncQuiet(){document.body.classList.toggle('motion-static',quiet());controls.querySelector('[data-quiet]').setAttribute('aria-pressed',String(quiet()));if(quiet()){running.forEach(a=>a.cancel());fields.forEach(f=>{cancelAnimationFrame(f.frame);draw(f,1);});const v=$('#hero-video');v.pause();}}
 controls.querySelector('[data-quiet]').addEventListener('click',()=>{manualPause=!quiet();syncQuiet();});reduced.addEventListener('change',syncQuiet);
 document.addEventListener('visibilitychange',()=>{if(document.hidden){running.forEach(a=>{try{a.finish();}catch{a.cancel();}});fields.forEach(f=>{cancelAnimationFrame(f.frame);draw(f,1);});}});
 new ResizeObserver(()=>fields.forEach(f=>draw(f,1))).observe(hero);
 panelMotion();opening();syncQuiet();
})();
